// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 fuzzBlockNumber, address caller) public {
        uint256 bn = bound(fuzzBlockNumber, 1, type(uint64).max);
        vm.roll(bn);

        vm.warp(block.timestamp + 1);

        vm.assume(caller != address(0));
        vm.deal(caller, 20 ether);

        vm.prank(caller);
        (bool ok,) = address(c).call{value: 10 ether}("");

        if (ok && (bn % 15 == 0)) {
            assertTrue(address(c).balance == 0);
        }
    }
}
